import json
d=json.load(open('/private/tmp/vista-task002-local-3x3-20260822-05/formal-task002-local-3x3-minimaxm3-20260822-05-pd-vista-replicate-02/workspace/DATA/products/PersonalizeForce.json'))
# Strict matching - messages that explicitly mention competitor names
competitors = ['tailorai', 'smartsuggest', 'personaai']
channel_participants = {}
for msg in d['slack']:
    user = msg.get('Message', {}).get('User', {})
    text_str = user.get('text', '')
    text_lower = text_str.lower()
    ch = msg.get('Channel', {})
    ch_name = ch.get('name', '')

    for comp in competitors:
        if comp in text_lower:
            if ch_name not in channel_participants:
                channel_participants[ch_name] = set()
            if user.get('userId'):
                channel_participants[ch_name].add(user.get('userId'))
            break

# Now get all unique users across all competitor discussions (including those who didn't explicitly name but participated)
all_competitor_users = set()
for ch in channel_participants.keys():
    for msg in d['slack']:
        user = msg.get('Message', {}).get('User', {})
        text_str = user.get('text', '')
        ts = user.get('timestamp', '')
        msg_ch = msg.get('Channel', {}).get('name', '')
        if msg_ch != ch:
            continue
        # Check if message is in a competitor discussion window (within ±1 hour of any competitor message in this channel)
        for ref_msg in d['slack']:
            ref_user = ref_msg.get('Message', {}).get('User', {})
            ref_text = ref_user.get('text', '').lower()
            ref_ts = ref_user.get('timestamp', '')
            ref_ch = ref_msg.get('Channel', {}).get('name', '')
            if ref_ch != ch:
                continue
            for comp in competitors:
                if comp in ref_text:
                    # Check if timestamps are close
                    try:
                        from datetime import datetime
                        ts_dt = datetime.fromisoformat(ts[:19])
                        ref_dt = datetime.fromisoformat(ref_ts[:19])
                        diff = abs((ts_dt - ref_dt).total_seconds())
                        if diff < 3600:  # within 1 hour
                            if user.get('userId'):
                                all_competitor_users.add(user.get('userId'))
                            break
                    except:
                        pass
                    break
            else:
                continue
            break

print("Users in competitor discussions (broad):")
for u in sorted(all_competitor_users):
    print(f"  {u}")
EOF

